import{_ as a,a0 as i,w as d,s,I as l,x as t,a1 as n,A as u,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"Ubuntu Touch 和 Android 双系统安装官方指南 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu Touch 和 Android 双系统安装官方指南 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu Touch 和 Android 双系统安装官方指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu Touch 和 Android 双系统安装官方指南 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/Ubuntu Touch and Android Dual Boot Installation","title":"Ubuntu Touch 和 Android 双系统安装官方指南","tag":"201405","desc":""},"relativePath":"201405/Ubuntu Touch and Android Dual Boot Installation.md","filePath":"[post].md"}'),p={name:"201405/Ubuntu Touch and Android Dual Boot Installation.md"};function b(h,o,U,A,g,m){const r=i("Link");return d(),s("div",null,[o[42]||(o[42]=l("h1",{id:"ubuntu-touch-和-android-双系统安装官方指南",tabindex:"-1"},[t("Ubuntu Touch 和 Android 双系统安装官方指南 "),l("a",{class:"header-anchor",href:"#ubuntu-touch-和-android-双系统安装官方指南","aria-label":"Permalink to “Ubuntu Touch 和 Android 双系统安装官方指南”"},"​")],-1)),l("p",null,[o[1]||(o[1]=t("（译注：本文译自",-1)),n(r,{href:"https://wiki.ubuntu.com/Touch/DualBootInstallation"},{default:u(()=>[...o[0]||(o[0]=[t("Ubuntu官方维基",-1)])]),_:1}),o[2]||(o[2]=t("）",-1))]),o[43]||(o[43]=e('<p>Ubuntu 双系统安装器是作为技术预览版本发布给开发者的，可以使得开发者同时在一台手机上安装 Ubuntu 系统和 Android 系统。该软件现阶段或最终的目标用户并非普通用户。开发者应该熟悉 Ubuntu 和 Android 系统的分区布局并且在出现问题的时候有能力手动刷回分区。</p><p>Ubuntu 双系统安装器是一些工程师花了一点时间内做出的一个内部臭鼬项目(译注：管理层不知的研究项目)。由于项目进展良好，所以决定向开发者社区发布预览版以供大家测试、学习或者完善。</p><p>双系统启动不是常规 Ubuntu 发布版本中的一部分。</p><h2 id="安装后可实现以下功能" tabindex="-1">安装后可实现以下功能 <a class="header-anchor" href="#安装后可实现以下功能" aria-label="Permalink to “安装后可实现以下功能”">​</a></h2><ul><li>一台可以在全功能的 Android 和 Ubuntu 系统之间切换的手机</li><li>Android 系统上：一个 Ubuntu Installer 应用，用来安装 Ubuntu 系统和切换到 Ubuntu 系统</li><li>Android 系统上：一个 SuperUser 超级用户管理器，用来为 Ubuntu 安装器授予权限</li><li>Ubuntu 系统上：一个 Ubuntu Dual Boot 应用，用来启动到 Android 系统</li><li>尚不支持在 Ubuntu 系统下的更新，但可以通过 Android 下的应用程序来进行系统更新</li></ul><h2 id="必要条件" tabindex="-1">必要条件 <a class="header-anchor" href="#必要条件" aria-label="Permalink to “必要条件”">​</a></h2><p>安装双系统启动，你需要：</p>',7)),l("ul",null,[l("li",null,[o[4]||(o[4]=l("strong",null,"一台Nexus 4 手机",-1)),o[5]||(o[5]=t(" (其他 ",-1)),n(r,{href:"https://wiki.ubuntu.com/Touch/Devices#Working_with_phablet-flash"},{default:u(()=>[...o[3]||(o[3]=[t("支持的 Nexus 手机",-1)])]),_:1}),o[6]||(o[6]=t(" 理论上也能安装，但是现在还没有经过测试。)",-1))]),o[7]||(o[7]=e('<li>手机安装 <strong>Android 4.4.2 或者更高的系统版本</strong> ，基于原厂固件或者 CyanogenMod 和 AOSP 的固件。</li><li>手机上需要有 <strong>2.7GB 剩余存储空间</strong> 用来安装Ubuntu。</li><li>桌面电脑上需要运行 <strong>ADB 工具</strong></li><li>手机应该 <strong>解锁 bootloader 并打开 USB 调试选项</strong>。按照安装步骤1到3来实现。如果你的手机已经解锁过 bootloader 并且打开了 USB 调试选项了，这一步可以<a href="#Installation">跳过&gt;</a>。</li>',4))]),o[44]||(o[44]=e(`<h3 id="步骤-1-桌面电脑设置" tabindex="-1">步骤 1 - 桌面电脑设置 <a class="header-anchor" href="#步骤-1-桌面电脑设置" aria-label="Permalink to “步骤 1 - 桌面电脑设置”">​</a></h3><p>为了连接手机并刷机，在电脑桌面上依照以下几步操作。</p><p><strong>设置Touch开发者预览工具（Touch Developer Preview Tools）的 PPA</strong></p><p>这些 PPA 是一个迷你库，其中包含安装过程中需要的一些额外软件。以下描述如何去启用和使用它。</p><p>这些 PPA 的包含工具和依赖库支持各个 Ubuntu 发行版，包括 12.04, 12.10, 13.04, 13.10 和 14.04等。 将以下的源地址列表加入 <code>/etc/apt/sources.list</code> 文件中来添加 Ubuntu Touch PPA。</p><p>在你的机器上按 <code>Ctrl+Alt+T</code> 开启终端窗口，运行以下命令。</p><pre><code>sudo add-apt-repository ppa:phablet-team/tools
</code></pre><p>在 Ubuntu 12.04系统上，还需要运行以下命令：</p><pre><code>sudo add-apt-repository ppa:ubuntu-sdk-team/ppa
</code></pre><p>然后运行：</p><pre><code>sudo apt-get update
sudo apt-get install ubuntu-device-flash
</code></pre><h3 id="步骤-1-5-备份android-可选" tabindex="-1">步骤 1.5 - 备份Android(可选) <a class="header-anchor" href="#步骤-1-5-备份android-可选" aria-label="Permalink to “步骤 1.5 - 备份Android(可选)”">​</a></h3><ul><li><p>确认开启开发者模式。点击 <code>设置 -&gt; 关于手机 -&gt; 版本号</code> (点击七次)</p></li><li><p>确认开启 USB 调试模式。点击 <code>设置 -&gt; 开发者选项 -&gt; USB 调试</code></p></li><li><p>在你的电脑上执行（译注：自然这是在Linux下，如Ubuntu里面执行的）</p><pre><code>  $ adb backup -apk -shared -all
</code></pre></li></ul><p>这样就将你的操作系统、应用程序和所有的数据备份为 backup.ab 文件了。以后在重新刷回 android 系统（或root、解锁等）的时候可以使用 <code>$ adb restore backup.ab</code> 命令恢复你所有的数据。</p><h3 id="步骤-2-手机解锁" tabindex="-1">步骤 2 - 手机解锁 <a class="header-anchor" href="#步骤-2-手机解锁" aria-label="Permalink to “步骤 2 - 手机解锁”">​</a></h3><p>如果手机已经解锁，那么跳过步骤 3。以下几步将擦除手机上所有的个人数据。</p><ol><li>关机，同时按住手机的开机键+音量上+音量下开机。</li><li>手机将开机到bootloader界面。</li><li>使用 USB 数据线将手机和电脑连接。</li><li>在电脑上按 <code>Ctrl+Alt+T</code> 打开一个终端。 键入 <code>sudo fastboot oem unlock</code> 并回车。</li><li>在手机上，接受解锁条款。</li><li>按开手机开机键开机。(屏幕上 Start 的箭头所向)</li></ol><p><strong>恢复手机出厂设置</strong></p><p>如果解锁 bootloader 后不断重启的话... 可以使用以下方法解决：</p><ol><li>在重启的过程中，同时按住 电源键+音量上+音量下 使得手机重返 fastboot 模式。</li><li>在 fastboot 模式下，使用音量键选择到 Recovery 选项后，按下开机键选中。</li><li>在 Recovery 模式下(Android 机器人 背景是个红色三角) 同时按住音量上键和开机键进入stock recovery 模式。再次强调，不要按住按钮不放，只是同时按他们。保证你按了正确的音量按钮。应该是右边的音量按钮的向上键。</li><li>一旦进入 Recovery 模式，恢复出厂设置并清空数据，然后重启平板，现在应该可以看到欢迎屏幕了。</li></ol><h3 id="步骤-3-初始化手机指南" tabindex="-1">步骤 3 - 初始化手机指南 <a class="header-anchor" href="#步骤-3-初始化手机指南" aria-label="Permalink to “步骤 3 - 初始化手机指南”">​</a></h3><p>按照以下步骤初始化手机</p><ol><li>如果没有启动，启动手机进 Android 系统</li><li>启用手机的 USB 调试模式 <ul><li>在冰激凌三明治 (版本 4.0) 上打开 USB 调试(<code>设置 &gt; 系统 &gt; 开发者选项 &gt; USB 调试</code>)</li><li>在果冻豆 (版本 4.1 和 4.2) 上打开 USB 调试，需要进 <code>设置, 关于 [手机|平板]</code> 菜单且点击版本号7次才能进入开发者选项。</li><li>在 4.2.2, (<code>设置 &gt; 关于</code> &gt; 点击版本号7次激活开发者选项菜单)</li><li>在其他版本的 Android 系统中，你通过 <code>设置 &gt; 开发者选项 &gt; USB 调试</code>来启用 USB 调试模式。您也需要接受手机上的主机密钥。</li><li>在工作站中 -&gt; <code>adb kill-server; adb start-server</code></li></ul></li><li>将手机和电脑通过USB数据线连接起来。 <ul><li>根据 Android 版本的不同，会弹出一个主机密匙的框，需要确认才能和电脑通信。</li><li>注意，<code>adb devices</code> 命令不应该显示为手机 &#39;offline&#39; 。如果显示手机离线，在超级用户模式下运行adb(<code>sudo adb kill-server; sudo adb start-server</code>)，然后将手机再次连接。</li><li>在某些情况下，手机仍然显示为离线，如果USB连接模式为 &#39;MTP&#39; (一些手机或版本的Android的默认模式)的话，就不会弹出主机密匙提示对话框。取消所有的USB连接模式选项的勾选(<code>设置 -&gt; 存储 -&gt; 菜单 -&gt; USB连接 -&gt; MTP, PTP</code>)也许能解决adb连接问题。</li></ul></li><li>记下现有手机镜像版本号，Android 系统，恢复系统时使用。可以使用 <code>设置 &gt; 关于手机 &gt; 版本号码</code> 查看版本号。</li></ol><p>最新版的 Nexus 10s 开启开发者模式后并没有完全启动。如果是这种情况的话，启动到 bootloader 后运行 &quot;<code>fastboot -w</code>&quot; 然后进入下一步。</p><h2 id="双系统启动安装和更新说明" tabindex="-1">双系统启动安装和更新说明<a name="Installation"></a> <a class="header-anchor" href="#双系统启动安装和更新说明" aria-label="Permalink to “双系统启动安装和更新说明”">​</a></h2><p>双系统新安装和升级在这部分过程实际上是相同的。</p><h3 id="在-android-系统中安装-ubuntu-安装器" tabindex="-1">在 Android 系统中安装 Ubuntu 安装器 <a class="header-anchor" href="#在-android-系统中安装-ubuntu-安装器" aria-label="Permalink to “在 Android 系统中安装 Ubuntu 安装器”">​</a></h3><p>注意：如果手机中有一个以前版本的 Ubuntu 双启动，更新前请首先使用 Android 应用程序卸载掉 Ubuntu 系统。推荐保存用户数据，只卸载掉基本的系统。</p>`,28)),l("ol",null,[l("li",null,[l("p",null,[o[9]||(o[9]=t("在电脑上下载双系统安装脚本到你的家目录。",-1)),n(r,{href:"http://humpolec.ubuntu.com/latest/dualboot.sh"},{default:u(()=>[...o[8]||(o[8]=[t("http://humpolec.ubuntu.com/latest/dualboot.sh",-1)])]),_:1})])]),o[10]||(o[10]=e(`<li><p>使用 <code>Ctrl+Alt+T</code> 组合键打开电脑终端。</p></li><li><p>运行以下命令赋予安装脚本可执行权限。</p><pre><code> chmod +x dualboot.sh
</code></pre></li><li><p>保证你的手机</p><ul><li>正常启动进入 Android 用户界面</li><li>启用 USB 调试选项</li><li>已经解锁了 bootloader</li></ul></li><li><p>使用 USB 数据线连接手机和电脑</p></li><li><p>在终端里运行以下命令安装双系统启动：</p><pre><code> ./dualboot.sh
</code></pre></li>`,5))]),o[45]||(o[45]=e(`<p>安装完成后，手机会重启数次。完成后，系统会启动到 Android 系统，你可以在手机的应用程序里面找到双启动应用程序 (“Ubuntu Dual Boot”) 。</p><p>或者，可以使用安装脚本的另一个替代方法，<a href="#DualBootInstallerReference">可以参考安装手册 &gt;</a>。</p><p>现在按照以下说明在 Android 下安装 Ubuntu。</p><h2 id="android-下安装-ubuntu" tabindex="-1">Android 下安装 Ubuntu <a class="header-anchor" href="#android-下安装-ubuntu" aria-label="Permalink to “Android 下安装 Ubuntu”">​</a></h2><p>注意：Ubuntu 安装需要手机上具有2.7GB以上的剩余内存空间。</p><ol><li><p>如果需要，也可以在手机和电脑USB连接状态下，终端运行以下命令来释放空间。(接受手机上的授权询问)</p><pre><code> adb shell &quot;su sh rm -rf /cache/*&quot;
</code></pre></li><li><p>在手机上，点击 apps 按钮打开 app 列表</p></li><li><p>查看列表找到 <strong>Ubuntu Dual Boot</strong> 图标并启动它</p></li><li><p>应用程序启动后按 <strong>Choose channel to install</strong> 并选择一个频道下载(推荐 <strong>utopic</strong> 频道)，请确保您勾选了“bootstrap”选项</p></li><li><p>下载完成后需要授权 SU 权限给应用程序。提示授权的时候，选择 <strong>Grant</strong> 按钮</p></li><li><p>按 <strong>Reboot to Ubuntu</strong> 按钮重启手机进入Ubuntu</p></li><li><p>标准手机重启过程后会启动到Android系统中</p></li></ol><p>注意：</p><ul><li>Ubuntu 安装器支持所有手机平板刷机工具（phablet-flash）支持的频道</li><li>选择了一个 Ubuntu 频道后，<strong>bootstrap</strong> 复选框可以让你选择清空 Ubuntu 的用户数据，如果不选中的话，用户数据将一直保留。第一次安装的话，选不选是没什么区别的</li><li>选中一个 Ubuntu 频道后，取消 <strong>latest version</strong> 复选框后可以选择一个特定版本号的镜像，否则，默认安装最新的镜像。</li><li>如果在安装过程下载镜像过程中，手机锁屏或者 Ubuntu 安装器在后台运行的话，安装按钮会变成 <strong>Resume install</strong> (恢复安装)。点击这个按钮会恢复到超级权限提示前的状态。</li></ul><h2 id="其他需要注意的" tabindex="-1">其他需要注意的 <a class="header-anchor" href="#其他需要注意的" aria-label="Permalink to “其他需要注意的”">​</a></h2><h3 id="更新到最新的-ubuntu-镜像" tabindex="-1">更新到最新的 Ubuntu 镜像 <a class="header-anchor" href="#更新到最新的-ubuntu-镜像" aria-label="Permalink to “更新到最新的 Ubuntu 镜像”">​</a></h3><p>根据双启动的经验：</p><ul><li>安装新版本的 Ubuntu 需要使用 Android 上的双启动应用程序</li><li>下载新版本的 Ubuntu 可以在 Android 或者 Ubuntu 下进行</li></ul><p>这实际上意味着可以有两种不同的方式更新 Ubuntu 镜像（译注：此处与前文不一致，究竟是否可在Ubuntu下更新，译者没有做过实验，可能已经支持了。）：</p><ul><li><strong>如果在android系统下</strong>，使用双启动应用程序更新 Ubuntu ，需要选择菜单选项中的 &quot;Uninstall Ubuntu&quot; ，然后应用程序会询问你是否保留 Ubuntu 用户数据。如果你想保留数据、通讯录、应用程序、图片、背景设置等，这些数据将会完整保留。另外，每次新版本的 Ubuntu 发布后，将会收到 Android 通知： <ul><li>对于稳定频道，应用每2天推送一次更新通知</li><li>对于推荐频道，应用每10小时推送一次更新通知</li></ul></li><li><strong>如果你使用的是 Ubuntu</strong>, 使用系统设置中的标准更新机制下载新版镜像，但是不要选择安装，下载完毕后，重新启动到 Android 系统中，启动双启动应用程序，程序会恢复更新。完成后，你可以再次切换到 Ubuntu系统中。</li></ul><p>要升级 Ubuntu 到最新版本，在 android 下的 Ubuntu 双启动应用程序中，卸载 Ubuntu 后，可以按照同样的安装步骤去下载新版本的 Ubuntu。</p><h3 id="双系统安装器参考命令" tabindex="-1">双系统安装器参考命令<a name="#DualBootInstallerReference"></a> <a class="header-anchor" href="#双系统安装器参考命令" aria-label="Permalink to “双系统安装器参考命令”">​</a></h3><p>大多数情况下，不带参数运行自动模式安装脚本就足够了。</p><p>dualboot.sh</p>`,18)),l("ul",null,[l("li",null,[o[12]||(o[12]=t("自动模式：监测",-1)),n(r,{href:"https://wiki.ubuntu.com/SuperUser"},{default:u(()=>[...o[11]||(o[11]=[t("超级用户",-1)])]),_:1}),o[13]||(o[13]=t("应用程序是否需要安装，并更新双系统安装应用程序。",-1))])]),o[46]||(o[46]=l("p",null,"dualboot.sh full",-1)),l("ul",null,[l("li",null,[o[15]||(o[15]=t("完整模式：安装",-1)),n(r,{href:"https://wiki.ubuntu.com/SuperUser"},{default:u(()=>[...o[14]||(o[14]=[t("超级用户",-1)])]),_:1}),o[16]||(o[16]=t("和双系统启动 Android 应用程序",-1))])]),o[47]||(o[47]=e(`<p>dualboot.sh update</p><ul><li>更新模式：安装或者更新 Android 下的双系统启动应用程序</li></ul><p>dualboot.sh channel $CHANNEL</p><ul><li>边载（Sideload）模式：通过指定的 Ubuntu 频道 ($CHANNEL) 下载最新的镜像到手机。命令启动 android 双系统应用程序并继续使用边载文件进行安装。</li></ul><p>dualboot.sh push ubuntu.tar.xz device.tar.xz version.tar.xz</p><ul><li>边载推送模式：将下载参数推送给双系统启动应用程序，作为参数启动双系统安装器进行安装。</li></ul><p>多个手机同时连到电脑上的时候，脚本还提供指定手机ID 的参数。手机ID为脚本的第一个参数。如果不指定手机ID的话，默认为第一个连接的手机。</p><pre><code>dualboot.sh &lt;device-id&gt; channel devel-customized
</code></pre><h3 id="使用自定义镜像服务器" tabindex="-1">使用自定义镜像服务器 <a class="header-anchor" href="#使用自定义镜像服务器" aria-label="Permalink to “使用自定义镜像服务器”">​</a></h3><p>如果你的手机不在官方支持列表中，需要使用第三方移植镜像服务器，你可以将自定义镜像服务器地址作为参数来使用双启动应用程序。这么办的话，打开终端，连接手机到电脑，运行以下命令(替换 $CUSTOM_SERVER_URL 为自定义服务器地址)：</p><pre><code>adb shell &quot;su sh &#39;cd /data/data/com.canonical.ubuntu.installer/files/ &amp;&amp; echo $CUSTOM_SERVER_URL &gt; custom_server &amp;&amp;  chmod 777 custom_server&#39;&quot;
</code></pre><p>下次启动双启动应用程序的时候，默认将使用自定义服务器地址而不是官方地址了。</p><h2 id="异常处理" tabindex="-1">异常处理 <a class="header-anchor" href="#异常处理" aria-label="Permalink to “异常处理”">​</a></h2><p>如果出现问题，安装双启动后无法进入 Android 和 Ubuntu 系统的话，你可以使用原始启动和恢复镜像恢复手机到最初状态。只有 recovery 分区被双启动修改了，当然你可以刷回原有的启动分区。</p><ol><li><p>下载手机的 Android 固件到你的PC上。</p></li><li><p>使用快捷键 <code>Ctrl+Alt+T</code> 打开终端</p></li><li><p>解压固件 tar 包并 cd 到其目录</p></li><li><p>运行以下命令以重启手机到 bootloader</p><pre><code> adb reboot bootloader
</code></pre></li><li><p>进入 bootloader 后，运行以下命令刷回启动分区：</p><pre><code> fastboot flash boot boot.img
</code></pre></li><li><p>不要退出 bootloader ，运行以下命令刷回 recovery 分区：</p><pre><code> fastboot flash recovery recovery.img
</code></pre></li><li><p>刷机完毕后，重启你的手机应该就可以进入 Android 系统了：</p><pre><code> fastboot reboot
</code></pre></li></ol><h2 id="致谢" tabindex="-1">致谢 <a class="header-anchor" href="#致谢" aria-label="Permalink to “致谢”">​</a></h2><p>双启动项目和其他 Ubuntu 项目一样都是开源的，你可以参与此项目，使得他更加完美！</p>`,17)),l("ul",null,[l("li",null,[n(r,{href:"https://bugs.launchpad.net/humpolec/+filebug"},{default:u(()=>[...o[17]||(o[17]=[t("Bug 报告 >",-1)])]),_:1})]),l("li",null,[n(r,{href:"https://code.launchpad.net/humpolec"},{default:u(()=>[...o[18]||(o[18]=[t("贡献代码 >",-1)])]),_:1})])]),o[48]||(o[48]=e('<h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to “FAQ”">​</a></h2><h3 id="双启动如何工作" tabindex="-1">双启动如何工作？ <a class="header-anchor" href="#双启动如何工作" aria-label="Permalink to “双启动如何工作？”">​</a></h3><p>基于 Android 的手机有一系列不同用途的分区。这些分区包括 <strong>/boot</strong>, <strong>/recovery</strong>, <strong>/system</strong> 和 <strong>/data</strong> 等。</p><ul><li><strong>boot</strong> 分区是 bootloader 正常启动的时候载入的。这个分区的启动镜像是由一个内核和ramdisk程序组成的。简而言之，bootloader 解压启动镜像，创建一个内存盘后将镜像考入，最后使用 <strong>初始化进程</strong> 启动内核。</li><li><strong>recovery</strong> 分区包含有恢复镜像，它只是一个不同的启动镜像。它也含有一个内核和内存盘程序，但是初始化可执行程序被换成了内存盘中的二进制的 recovery 程序。</li><li><strong>system</strong> 分区含有所有的只读系统文件 (除了内存盘中的)供初始化进程载入。</li><li><strong>data</strong> 分区是供系统写入用户数据的可读写分区。</li></ul><p>Ubuntu 以稍微不同的方式使用这些分区</p>',5)),l("ul",null,[o[23]||(o[23]=l("li",null,[l("strong",null,"boot"),t(" 和 "),l("strong",null,"recovery"),t(" 分区的作用和 Android 中一样。")],-1)),l("li",null,[o[20]||(o[20]=l("strong",null,"system 镜像",-1)),o[21]||(o[21]=t(" 含有在 ",-1)),n(r,{href:"http://www.ibm.com/developerworks/cn/linux/l-lxc-containers/"},{default:u(()=>[...o[19]||(o[19]=[t("LXC",-1)])]),_:1}),o[22]||(o[22]=t(" 中执行的 Android 部分的程序。",-1))]),o[24]||(o[24]=l("li",null,[l("strong",null,"data"),t(" 分区下的 "),l("strong",null,"/data/ubuntu/"),t(" 目录含有Ubuntu系统")],-1))]),o[49]||(o[49]=e('<p>为了保证用户可以返回 Android 原来的系统，Android 系统的启动镜像是不允许修改的，因为原始内核必须保存。<strong>所以使用 recovery 分区去启动Ubuntu</strong></p><h3 id="双启动可以运行在那个版本的-android-系统下" tabindex="-1">双启动可以运行在那个版本的 Android 系统下？ <a class="header-anchor" href="#双启动可以运行在那个版本的-android-系统下" aria-label="Permalink to “双启动可以运行在那个版本的 Android 系统下？”">​</a></h3><ul><li>普通 Android 或 AOSP 4.4.2 或更高版本。</li><li>CyanogenMod (基于 Android 4.4.2 或更高版本).</li></ul><h3 id="双启动可以运行在那些手机上" tabindex="-1">双启动可以运行在那些手机上？ <a class="header-anchor" href="#双启动可以运行在那些手机上" aria-label="Permalink to “双启动可以运行在那些手机上？”">​</a></h3><p>双启动通过测试可以运行在以下手机中：</p><ul><li>Nexus 4</li><li>Nexus 7</li><li>Nexus 10</li></ul><h3 id="双启动支持那些已发布版本的-ubuntu" tabindex="-1">双启动支持那些已发布版本的 Ubuntu？ <a class="header-anchor" href="#双启动支持那些已发布版本的-ubuntu" aria-label="Permalink to “双启动支持那些已发布版本的 Ubuntu？”">​</a></h3><p>双启动支持的所有手机平板刷机工具（phablet-flash）支持的系统。</p><h3 id="android-和-ubuntu-如何共享用户数据分区" tabindex="-1">Android 和 Ubuntu 如何共享用户数据分区？ <a class="header-anchor" href="#android-和-ubuntu-如何共享用户数据分区" aria-label="Permalink to “Android 和 Ubuntu 如何共享用户数据分区？”">​</a></h3><p>用户数据分区也放在 Ubuntu 系统镜像 /data/system.img, 大约有2GB。</p><p>Ubuntu swap 文件在用户数据分区 /data/SWAP.img (大约540MB)。</p><p>Ubuntu 的用户和系统数据也可以在以下目录找到：</p><ul><li>/data/user-data</li><li>/data/system-data</li></ul><p>Android 数据分区的使用方式不变。</p><h3 id="安装双启动后是否无法启动进入-recovery" tabindex="-1">安装双启动后是否无法启动进入 recovery？ <a class="header-anchor" href="#安装双启动后是否无法启动进入-recovery" aria-label="Permalink to “安装双启动后是否无法启动进入 recovery？”">​</a></h3><p>安装双启动后，recovery 分区被 Ubuntu 启动镜像占用。这意味着启动到 recovery 模式下，就启动了Ubuntu 。</p><p>使用 recovery 的功能会在未来发布。不过当卸载掉 Ubuntu 镜像后，Ubuntu Install 应用会恢复原始的 recovery 分区(普通的 Android 或 CWM)。</p><h3 id="如果用双启动替换掉-recovery-分区的话-是否还可以更新-android-系统" tabindex="-1">如果用双启动替换掉 recovery 分区的话，是否还可以更新 Android 系统？ <a class="header-anchor" href="#如果用双启动替换掉-recovery-分区的话-是否还可以更新-android-系统" aria-label="Permalink to “如果用双启动替换掉 recovery 分区的话，是否还可以更新 Android 系统？”">​</a></h3><p>可以，使用双启动应用程序中的 &quot;准备更新安卓&quot; 选项。这会将原始 Android recovery 分区恢复，为 Android 系统更新做准备。这显然会删除 recovery 分区中安装的 Ubuntu 系统，但是使用双系统应用程序可以在 Android 系统更新后很容易重新安装。</p><p>任何情况下，你都可以卸载双启动并恢复原始的 recovery 分区。</p><h3 id="我可以卸载双启动吗" tabindex="-1">我可以卸载双启动吗？ <a class="header-anchor" href="#我可以卸载双启动吗" aria-label="Permalink to “我可以卸载双启动吗？”">​</a></h3><p>可以，使用 Android 版本双启动应用程序卸载 Ubuntu 后，原有的 recovery 分区数据会恢复到安装前的状态。</p><p>卸载 Ubuntu 的同时也会删除 Ubuntu 系统镜像和交换文件。如果需要，Ubuntu 用户数据也可以被删除。</p><h3 id="双启动应用程序安装了一个超级用户应用-我可以使用一个第三方的超级用户应用代替它吗" tabindex="-1">双启动应用程序安装了一个超级用户应用，我可以使用一个第三方的超级用户应用代替它吗？ <a class="header-anchor" href="#双启动应用程序安装了一个超级用户应用-我可以使用一个第三方的超级用户应用代替它吗" aria-label="Permalink to “双启动应用程序安装了一个超级用户应用，我可以使用一个第三方的超级用户应用代替它吗？”">​</a></h3>',24)),l("p",null,[o[26]||(o[26]=t("当然可以了！提供的 ",-1)),n(r,{href:"https://wiki.ubuntu.com/SuperUser"},{default:u(()=>[...o[25]||(o[25]=[t("超级用户",-1)])]),_:1}),o[27]||(o[27]=t(" 应用只是为了那些没有安装它的用户的。",-1))]),l("p",null,[o[29]||(o[29]=t("然而，需要注意一点：项目测试中只测试使用了来自 ",-1)),n(r,{href:"https://wiki.ubuntu.com/CyanogenMod"},{default:u(()=>[...o[28]||(o[28]=[t("CyanogenMod",-1)])]),_:1}),o[30]||(o[30]=t(" 版本或者 dualboot.sh 脚本安装的超级用户应用。但是只要你使用和测试中用的类似的应用的话，一般也不会有问题的。",-1))]),o[50]||(o[50]=e('<h3 id="安装-ubuntu-中-我是否可以删除用户数据后切换频道" tabindex="-1">安装 Ubuntu 中，我是否可以删除用户数据后切换频道？ <a class="header-anchor" href="#安装-ubuntu-中-我是否可以删除用户数据后切换频道" aria-label="Permalink to “安装 Ubuntu 中，我是否可以删除用户数据后切换频道？”">​</a></h3><p>可以，但是有些东西没有测试过，所以有些应用也许无法正常工作。这个问题也存在于切换版本的情况。</p><h3 id="我能否设置默认启动-ubuntu-而将-android-启动移动到-recovery-分区" tabindex="-1">我能否设置默认启动 Ubuntu 而将 Android 启动移动到 recovery 分区？ <a class="header-anchor" href="#我能否设置默认启动-ubuntu-而将-android-启动移动到-recovery-分区" aria-label="Permalink to “我能否设置默认启动 Ubuntu 而将 Android 启动移动到 recovery 分区？”">​</a></h3><p>目前为止交换默认启动操作系统是不可行的。但是如果有需求的话我们会想办法支持的。</p><h3 id="为什么使用-recovery-分区启动-ubuntu-系统而不是使用一个-android-和-ubuntu-结合的镜像来启动" tabindex="-1">为什么使用 recovery 分区启动 Ubuntu 系统而不是使用一个 Android 和 Ubuntu 结合的镜像来启动？ <a class="header-anchor" href="#为什么使用-recovery-分区启动-ubuntu-系统而不是使用一个-android-和-ubuntu-结合的镜像来启动" aria-label="Permalink to “为什么使用 recovery 分区启动 Ubuntu 系统而不是使用一个 Android 和 Ubuntu 结合的镜像来启动？”">​</a></h3><p>最开始设计双启动的时候原则就是不和某个特定版本和类型的 Android 系统捆绑，留给用户自己选择的权利。所以就没有改动 Android 启动镜像和内核。</p><p>最后我们选择利用 recovery 分区启动 Ubuntu，并在需要的时候就恢复到其原始状态。</p><h3 id="我已经安装了一个-cwm-recovery-而且知道如何使用-我可否使用-zip-文件手动刷机" tabindex="-1">我已经安装了一个 CWM recovery 而且知道如何使用，我可否使用 zip 文件手动刷机？ <a class="header-anchor" href="#我已经安装了一个-cwm-recovery-而且知道如何使用-我可否使用-zip-文件手动刷机" aria-label="Permalink to “我已经安装了一个 CWM recovery 而且知道如何使用，我可否使用 zip 文件手动刷机？”">​</a></h3><p>绝对可以，我们提供的 dualboot.sh 是为了使得安装应用和 recovery 更容易。如果你想手动安装recovery 也是可以的。参看 dualboot.sh 脚本的源码来操作。</p><h3 id="为什么-ubuntu-安装器需要使用-recovery-安装到-system-分区里" tabindex="-1">为什么 Ubuntu 安装器需要使用 recovery 安装到 system 分区里？ <a class="header-anchor" href="#为什么-ubuntu-安装器需要使用-recovery-安装到-system-分区里" aria-label="Permalink to “为什么 Ubuntu 安装器需要使用 recovery 安装到 system 分区里？”">​</a></h3><p>Ubuntu 安装器需要安装为 Android （预置的）系统应用。 和用户安装在用户分区的应用不一样，系统应用始终活动在系统分区中，保证可以获取第三方软件可以获取的的最高的权限。</p><p>其实 Ubuntu 安装器需要获取的权限只有两个：<strong>缓存分区写入权限</strong>，用来下载 Ubuntu 安装文件；和<strong>电源管理</strong>，用来重启系统。</p><hr>',13)),l("p",null,[o[32]||(o[32]=t("via: ",-1)),n(r,{href:"https://wiki.ubuntu.com/Touch/DualBootInstallation"},{default:u(()=>[...o[31]||(o[31]=[t("https://wiki.ubuntu.com/Touch/DualBootInstallation",-1)])]),_:1})]),l("p",null,[o[35]||(o[35]=t("译者：",-1)),n(r,{href:"https://github.com/shipsw"},{default:u(()=>[...o[33]||(o[33]=[t("shipsw",-1)])]),_:1}),o[36]||(o[36]=t(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:u(()=>[...o[34]||(o[34]=[t("wxy",-1)])]),_:1})]),l("p",null,[o[39]||(o[39]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...o[37]||(o[37]=[t("LCTT",-1)])]),_:1}),o[40]||(o[40]=t(" 原创翻译，",-1)),n(r,{href:"http://linux.cn/"},{default:u(()=>[...o[38]||(o[38]=[t("Linux中国",-1)])]),_:1}),o[41]||(o[41]=t(" 荣誉推出",-1))])])}const v=a(p,[["render",b]]);export{c as __pageData,v as default};
